sp_widget.client_script:
api.controller=function($rootScope, $timeout) {
  // widget controller
  var c = this;
	var bc = [{label: c.data.widgetTitle, url: '#'}];
	$timeout(function() {
		$rootScope.$broadcast('sp.update.breadcrumbs', bc);
	});

	function handleToolTip() {
		$timeout(function() {
			$(".tool-tip-title").each(function(index) {
				if (this.offsetWidth >= this.scrollWidth) {
					$(this).removeAttr("title");
					$(this).removeAttr("data-original-title");
				}
			});
		}, 100);
	}

	handleToolTip();

	$timeout(function() {
		$('.survey-title a').first().focus();
	});

	$(document).on('mousedown', ".survey-title a[aria-describedby]", function() {
    	$(".survey-title a[aria-describedby]").tooltip('hide');
	});
}

sp_widget.css:
/*
===============================================================================
SURVEY / ASSESSMENT WIDGET — Modern Glassmorphism Theme
Paste into the CSS field of your survey/assessment widget
===============================================================================
*/

/* Instance Display / Subtitle Text */
.instance-display-text {
  padding: 2px 0;
  color: $brand-primary !important;
  font-size: 0.8rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

/* Panel / Card Spacing */
.survey-panel-spacer {
  margin: 16px 0;
  padding: 18px 20px;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(8px);
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.04);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.survey-panel-spacer:hover {
  transform: translateY(-2px);
  border-color: #CBD5E1;
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.08);
}

/* Survey Title & Links */
.survey-title {
  font-weight: 800 !important;
  font-size: 1rem !important;
  line-height: 1.4;
  margin-bottom: 4px;
}

.survey-title a {
  color: #0F172A !important;
  text-decoration: none !important;
  transition: color 0.2s ease;
}

.survey-title a:hover {
  color: $brand-primary !important;
}

/* Card Bottom Metadata */
.card-bottom {
  margin-top: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* Progress Bar Track */
.progress-bar {
  width: 100%;
  height: 8px;
  border-radius: 999px;
  background: #E2E8F0; /* Soft modern neutral gray track */
  margin-top: 8px;
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.06);
}

/* Progress Bar Fill */
.progress-bar-inner {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, $brand-primary 0%, $brand-success 100%); /* SPAR Brand Gradient Fill */
  transition: width 0.4s ease-in-out;
}

/* Flexible Container Height */
.container-height {
  min-height: 20px;
  display: flex;
  align-items: center;
}

sp_widget.script:
(function() {
  // populate the 'data' object
  data.maxRecords = options.maxRecords || 5;

  // Explicitly call SPSurveyAPI from the sn_portal_surveys scope
  var sp = new sn_portal_surveys.SPSurveyAPI();

  options.showAll = $sp.getParameter('id') == 'my_surveys';
  if ($sp.getParameter('id') != 'my_surveys') {
      if (options.widgetTitle && options.widgetTitle.length > 0) {
          data.widgetTitle = gs.getMessage(options.widgetTitle);
      } else {
          data.widgetTitle = gs.getMessage("My Assessments and Surveys");
      }
      data.encodedWidgetTitle = encodeURIComponent(data.widgetTitle);
  } else {
      data.widgetTitle = $sp.getParameter('title') ? gs.getMessage($sp.getParameter('title')) : gs.getMessage("My Assessments and Surveys");
  }

  sp.getSurveys(data.maxRecords, options.showAll, data, true);

  if (data.instances) {
      data.instances.forEach(function(instance) {
          if (!!instance.description)
              instance.description = $sp.stripHTML(instance.description);

          var percentAnswered = parseInt(instance.portal_progress).toFixed(0) + '%';
          instance.progress_text = gs.getMessage("{0} complete", percentAnswered);
          instance.due_display_message = instance.due_display;

          if (instance.due_days < -1)
              instance.due_display_message = gs.getMessage("Due in {0} days", (0 - instance.due_days) + '');
          else if (instance.due_days == -1)
              instance.due_display_message = gs.getMessage("Due in 1 day");
      });
  }
})();
